INSERT INTO product_image_analysis (product_id, fingerprint, source, work, information, published, status, updated_at) VALUES ('10679311106188', '3d45b58e9ad6d2d6289c0ba0447152c24e6d42148854886d1a77bd5758d632e9', '{"id":"gid://shopify/Product/10679311106188","title":"Medicube PDRN Pink Peptide Serum","handle":"revitalizing-salmon-dna-lifting-serum","productType":"","vendor":"Maison & Co.","description":"This advanced facial serum is a breakthrough in skincare designed to rejuvenate and repair your skin at the deepest level. Enriched with the exceptional properties of Salmon DNA and PDRN (Polydeoxyribonucleotide), it works at a cellular level to promote skin regeneration, helping to restore your skin’s youthful vitality. Its lightweight, smooth liquid texture absorbs effortlessly into the skin, making it suitable for daily use and compatibility with your favorite moisturizers or makeup. Ideal for those who want to combat early signs of aging, dullness, and loss of firmness, this serum is perfect for busy individuals who desire visible results without exposing their skin to harsh chemicals. If your goal is a smoother, more lifted, and resilient complexion that radiates health, this formula addresses multiple concerns—such as fine lines, sagging, uneven texture, and dehydration—all in one nourishing treatment. Key features include a powerful blend of reparative ingredients that boost skin’s elasticity and hydration while promoting cell repair. Its nourishing components stimulate the skin’s natural processes, leading to a softer, plumper, and more radiant appearance. The serum is gentle enough for sensitive skin and free from high-concern chemicals, making it a safe choice for those with sensitivities. Embrace the emotional benefit of seeing your skin transform—feeling confident with a luminous, youthful glow that enhances your natural beauty. With consistent use, you can expect a visibly firmer, more resilient complexion that ages gracefully, restoring your self-esteem and empowering you to face each day with a fresh, radiant look. What sets this serum apart is its innovative use of PDRN derived from salmon DNA, a hallmark of premium Korean skincare that is renowned for its ability to repair and renew skin at a cellular level. Paired with peptides and other nourishing ingredients, it offers a luxurious, scientifically advanced treatment that delivers faster, safer, and more noticeable results compared to traditional options. Experience the power of Korean skincare excellence and transform your skin into a radiant, youthful masterpiece.","descriptionHtml":"<p>This advanced facial serum is a breakthrough in skincare designed to rejuvenate and repair your skin at the deepest level. Enriched with the exceptional properties of Salmon DNA and PDRN (Polydeoxyribonucleotide), it works at a cellular level to promote skin regeneration, helping to restore your skin’s youthful vitality. Its lightweight, smooth liquid texture absorbs effortlessly into the skin, making it suitable for daily use and compatibility with your favorite moisturizers or makeup. Ideal for those who want to combat early signs of aging, dullness, and loss of firmness, this serum is perfect for busy individuals who desire visible results without exposing their skin to harsh chemicals. If your goal is a smoother, more lifted, and resilient complexion that radiates health, this formula addresses multiple concerns—such as fine lines, sagging, uneven texture, and  dehydration—all in one nourishing treatment. Key features include a powerful blend of reparative ingredients that boost skin’s elasticity and hydration while promoting cell repair. Its nourishing components stimulate the skin’s natural processes, leading to a softer, plumper, and more radiant appearance. The serum is gentle enough for sensitive skin and free from high-concern chemicals, making it a safe choice for those with sensitivities. Embrace the emotional benefit of seeing your skin transform—feeling confident with a luminous, youthful glow that enhances your natural beauty. With consistent use, you can expect a visibly firmer, more resilient complexion that ages gracefully, restoring your self-esteem and empowering you to face each day with a fresh, radiant look. What sets this serum apart is its innovative use of PDRN derived from salmon DNA, a hallmark of premium Korean skincare that is renowned for its ability to repair and renew skin at a cellular level. Paired with peptides and other nourishing ingredients, it offers a luxurious, scientifically advanced treatment that delivers faster, safer, and more noticeable results compared to traditional options. Experience the power of Korean skincare excellence and transform your skin into a radiant, youthful masterpiece.</p>","tags":[],"updatedAt":"2026-10-10T12:25:03Z","productId":"10679311106188","metadata":[],"metadataAccessible":false,"images":[{"id":"gid://shopify/ProductImage/52140356829324","url":"https://cdn.shopify.com/s/files/1/0795/9570/0364/files/Pink_Rose_Serum_Splash_Advertisement.png?v=1791440553","width":1254,"height":1254,"altText":null},{"id":"gid://shopify/ProductImage/51991248175244","url":"https://cdn.shopify.com/s/files/1/0795/9570/0364/files/Sdf54a867346842a590cac011bbd31ce3G.webp?v=1791131757","width":1200,"height":1200,"altText":null},{"id":"gid://shopify/ProductImage/51991248011404","url":"https://cdn.shopify.com/s/files/1/0795/9570/0364/files/Sf4a14a6e16e94b079ed17c1b5d756c4fi.webp?v=1791131756","width":1200,"height":1200,"altText":null},{"id":"gid://shopify/ProductImage/51992717590668","url":"https://cdn.shopify.com/s/files/1/0795/9570/0364/files/IMG-5646.jpg?v=1791133968","width":922,"height":1156,"altText":null},{"id":"gid://shopify/ProductImage/51992717623436","url":"https://cdn.shopify.com/s/files/1/0795/9570/0364/files/IMG-5647.jpg?v=1791133968","width":736,"height":981,"altText":null},{"id":"gid://shopify/ProductImage/51991248076940","url":"https://cdn.shopify.com/s/files/1/0795/9570/0364/