ived information is awaiting review."],"updatedAt":"2026-10-10T20:50:49.385Z"}'::jsonb, '{"productId":"10682294960268","handle":"age-defying-firming-serum","title":"Medicube EGF Nad Firming Serum","fingerprint":"79766498128fd1ce54a8a1d28a9c8b5c230398fb73540e7ccec809cda3a011eb","category":"skincare","status":"needs_review","facts":[],"comparisons":[],"imagesTotal":10,"imagesInspected":10,"reasons":[],"updatedAt":"2026-10-10T20:50:49.385Z"}'::jsonb, 'needs_review', '2026-10-10T20:50:49.385Z'::timestamptz) ON CONFLICT (product_id) DO NOTHING;
INSERT INTO product_image_analysis (product_id, fingerprint, source, work, information, published, status, updated_at) VALUES ('10691183050892', '13b423dd8a25355038628f07f7d0c2dcbe731559e6e0e5aab23214c215f06088', '{"id":"gid://shopify/Product/10691183050892","title":"Revitalize Eye Therapy Patches","handle":"revitalize-eye-therapy-patches","productType":"","vendor":"Maison & Co.","description":"These hydrogel eye patches are a powerful skincare solution designed to revitalize tired, dull, or puffy under-eye areas. Crafted with innovative hydrogel material, they comfortably conform to the delicate skin beneath your eyes, ensuring maximum contact for optimal absorption of potent ingredients. This allows the patches to work effectively while you rest, unwind, or even during those quick moments between busy tasks. Perfect for women who lead active, demanding lives and want to maintain a fresh, youthful appearance without lengthy routines, these patches are your go-to for rapid results. Whether you''re dealing with early signs of aging, persistent dark circles, or morning puffiness, they deliver targeted care precisely where you need it most. The hero ingredients include PDRN, Caffeine, and Collagen. PDRN supports skin regeneration, encouraging natural repair and renewal to combat signs of fatigue and aging. Caffeine helps reduce swelling and puffiness, promoting a more alert, awake look in minutes. Collagen boosts elasticity and firmness, smoothing fine lines and sagging skin for a visibly more radiant appearance. Together, these ingredients deliver noticeable improvements—eyes that seem more vibrant, smoother, and refreshed after just 10 minutes. The soothing cooling sensation during application not only enhances comfort but also contributes to immediate relaxation, turning your skincare moment into a mini spa experience. These patches aren’t just for the under-eye area—they can also be applied to smile lines, forehead, or neck zones that need hydration and firmness, making them a versatile addition to your skincare routine. What makes these patches truly stand out is their blend of cutting-edge hydrogel technology with high-performance ingredients, giving you faster, more visible results than many traditional remedies. In a busy world where time is precious, they provide an effortless way to restore and protect your skin’s youthful glow. With consistent use, you can expect smoother skin, reduced puffiness, deeper hydration, and a brighter overall complexion. They empower you to face each day feeling confident, energized, and ready to take on whatever comes your way—all with a simple, effective skincare step that fits seamlessly into your busy lifestyle.","descriptionHtml":"These hydrogel eye patches are a powerful skincare solution designed to revitalize tired, dull, or puffy under-eye areas. Crafted with innovative hydrogel material, they comfortably conform to the delicate skin beneath your eyes, ensuring maximum contact for optimal absorption of potent ingredients. This allows the patches to work effectively while you rest, unwind, or even during those quick moments between busy tasks.\n\nPerfect for women who lead active, demanding lives and want to maintain a fresh, youthful appearance without lengthy routines, these patches are your go-to for rapid results. Whether you''re dealing with early signs of aging, persistent dark circles, or morning puffiness, they deliver targeted care precisely where you need it most.\n\nThe hero ingredients include PDRN, Caffeine, and Collagen. PDRN supports skin regeneration, encouraging natural repair and renewal to combat signs of fatigue and aging. Caffeine helps reduce swelling and puffiness, promoting a more alert, awake look in minutes. Collagen boosts elasticity and firmness, smoothing fine lines and sagging skin for a visibly more radiant appearance. Together, these ingredients deliver noticeable improvements—eyes that seem more vibrant, smoother, and refreshed after just 10 minutes.\n\nThe soothing cooling sensation during application not only enhances comfort but also contributes to immediate relaxation, turning your skincare moment into a mini spa experience. These patches aren’t just for the under-eye area—they can also be applied to smile lines, forehead, or neck zones that need hydration and firmness, making them a versatile addition to your skincare routine.\n\nWhat makes these patches truly stand out is their blend of cutting-edge hydrogel technology with high-performance ingredients, giving you faster, more visible results than many traditional remedies. In a busy world where time is precious, they provide an effortless way to restore and protect your skin’s youthful glow.\n\nWith consistent use, you can expect smoother skin, reduced puffiness, deeper hydration, and a brighter overall complexion. They empower you to face each day feeling confident, energized, and ready to take on whatever comes your way—all with a simple, effective skincare step that fits seamlessly into your busy lifestyle.","tags":[],"updatedAt":"2026-10-10T12:25:05Z","productId":"10691183050892","metadata":[],"metadataAccessible":false,"images":[{"id":"gid://shopify/ProductImage/52071093960844","url":"https://cdn.shopify.com/s/files/1/0795/9570/0364/files/61uiYF9sttL._SL1500.jpg?v=1791303424","width":1500,"height":1500,"altText":null},{"id":"gid://shopify/ProductImage/52071093993612","url":"https://cdn.shopify.com/s/files/1/0795/9570/0364/files/71TB_8ze3bL._SL1500.jpg?v=1791303424","width":1500,"height":1500,"altText":null},{"id":"gid://shopify/ProductImage/52071094026380","url":"https://cdn.shopify.com/s/files/1/0795/9570/0364/files/71sDU5uYnTL._SL1500.jpg?v=1791303424","width":1500,"height":1500,"altText":null},{"id":"gid://shopify/ProductImage/52071094059148","url":"https://cdn.shopify.com/s/files/1/0795/9570/0364/files/81Ku1Mnjf9L._SL1500.jpg?v=1791303424","width":1500,"height":1500,"altText":null},{"id":"gid://shopify/ProductImage/52071094091916","url":"https://