INSERT INTO product_image_analysis (product_id, fingerprint, source, work, information, published, status, updated_at) VALUES ('10691183181964', '3993e85f61e0ca454200cfe5159491db6ed6de42270318b556ed7433300bf5a4', '{"id":"gid://shopify/Product/10691183181964","title":"Youthful Glow Multi-Balm Stick","handle":"youthful-glow-multi-balm-stick","productType":"","vendor":"Maison & Co.","description":"This multi-purpose balm stick is a powerful skincare solution designed to rejuvenate and enhance your face and body with minimal effort. Crafted in a convenient, hygienic stick format, it offers targeted application that easily fits into your busy lifestyle. Whether you''re dealing with hollow cheeks, fine lines, dark circles, dullness, or loss of firmness, this all-in-one balm works to restore a more youthful, radiant appearance. Ideal for women juggling careers, family, and self-care, this product addresses common signs of aging and skin fatigue. It aims to boost confidence by delivering quick, visible improvements, helping you look refreshed and vibrant throughout the day. No more complicated routines or multiple products—just one effective solution to achieve that glow. At the heart of this balm is a blend of advanced ingredients. Volufiline visibly increases fullness in hollow areas like under the eyes and cheeks, resulting in a plumper, more youthful look. Enriched with PDRN—a regenerative ingredient—plus Collagen, NAD, Peptides, and Retinol, it deeply supports skin elasticity, hydration, and resilience, promoting a firm and smooth surface. The inclusion of caffeine and vitamin E works against dark circles, puffiness, and uneven skin tone, leaving your complexion brighter and more balanced. The balm’s rich, melting texture glides effortlessly onto the skin, delivering a comfortable, non-sticky feel that doesn’t interfere with your daily activities. Its stick format makes precise, mess-free application simple—perfect for quick touch-ups throughout the day, whether at home, at work, or on the go. Free from artificial colors and fragrances, it’s gentle enough to use around sensitive areas like the under-eye and lips, making it suitable for all skin types, including sensitive skin. Imagine starting each day with skin that feels as good as it looks—more radiant, plump, and resilient. This balm empowers you to maintain a natural, youthful glow effortlessly, boosting your confidence and helping you face every day with renewed vibrancy. It’s not just skincare; it’s a daily boost of self-esteem wrapped up in an easy, effective stick.","descriptionHtml":"This multi-purpose balm stick is a powerful skincare solution designed to rejuvenate and enhance your face and body with minimal effort. Crafted in a convenient, hygienic stick format, it offers targeted application that easily fits into your busy lifestyle. Whether you''re dealing with hollow cheeks, fine lines, dark circles, dullness, or loss of firmness, this all-in-one balm works to restore a more youthful, radiant appearance.\n\nIdeal for women juggling careers, family, and self-care, this product addresses common signs of aging and skin fatigue. It aims to boost confidence by delivering quick, visible improvements, helping you look refreshed and vibrant throughout the day. No more complicated routines or multiple products—just one effective solution to achieve that glow.\n\nAt the heart of this balm is a blend of advanced ingredients. Volufiline visibly increases fullness in hollow areas like under the eyes and cheeks, resulting in a plumper, more youthful look. Enriched with PDRN—a regenerative ingredient—plus Collagen, NAD, Peptides, and Retinol, it deeply supports skin elasticity, hydration, and resilience, promoting a firm and smooth surface. The inclusion of caffeine and vitamin E works against dark circles, puffiness, and uneven skin tone, leaving your complexion brighter and more balanced.\n\nThe balm’s rich, melting texture glides effortlessly onto the skin, delivering a comfortable, non-sticky feel that doesn’t interfere with your daily activities. Its stick format makes precise, mess-free application simple—perfect for quick touch-ups throughout the day, whether at home, at work, or on the go. Free from artificial colors and fragrances, it’s gentle enough to use around sensitive areas like the under-eye and lips, making it suitable for all skin types, including sensitive skin.\n\nImagine starting each day with skin that feels as good as it looks—more radiant, plump, and resilient. This balm empowers you to maintain a natural, youthful glow effortlessly, boosting your confidence and helping you face every day with renewed vibrancy. It’s not just skincare; it’s a daily boost of self-esteem wrapped up in an easy, effective stick.","tags":[],"updatedAt":"2026-10-10T12:25:05Z","productId":"10691183181964","metadata":[],"metadataAccessible":false,"images":[{"id":"gid://shopify/ProductImage/52071096254604","url":"https://cdn.shopify.com/s/files/1/0795/9570/0364/files/613iSS1QL9L._SL1500.jpg?v=1791303432","width":1500,"height":1500,"altText":null},{"id":"gid://shopify/ProductImage/52071096287372","url":"https://cdn.shopify.com/s/files/1/0795/9570/0364/files/71k3yJgTJXL._SL1500.jpg?v=1791303432","width":1500,"height":1500,"altText":null},{"id":"gid://shopify/ProductImage/52071096320140","url":"https://cdn.shopify.com/s/files/1/0795/9570/0364/files/71nURDQsFDL._SL1500.jpg?v=1791303431","width":1500,"height":1500,"altText":null},{"id":"gid://shopify/ProductImage/52071096352908","url":"https://cdn.shopify.com/s/files/1/0795/9570/0364/files/71f1w1hsbvL._SL1500.jpg?v=1791303432","width":1500,"height":1500,"altText":null},{"id":"gid://shopify/ProductImage/52071096385676","url":"https://cdn.shopify.com/s/files/1/0795/9570/0364/files/81ytL1CRXdL._SL1500.jpg?v=1791303432","width":1500,"height":1500,"altText":null},{"id":"gid://shopify/ProductImage/52071096418444","url":"https://cdn.shopify.com/s/files/1/0795/9570/0364/files/711cFSczGlL._SL1500.jpg?v=1791303432","width":1500,"height":1500,"altText":null},{"id":"gid://shopify/ProductImage/52071096451212","url":"https://cdn.shopify.com/s/files/1/0795/9570/0364/files/71S7clKP7nL._SL1500.jpg?v=1791303432","width":1500,"height":1500,"altText":null},{"id":"gid://shopify/ProductImage/52071096483980","url":"https://cdn.shopify.com/s/files/1/0795/9570/0364/files/811k4lMk_oL._SL1500.jpg?v=1791303432","width":1500,"height":1500,"altText":null}]}'::jsonb, '{"description":{"comparison":{"afterRegion":null,"beforeRegion":null,"confidence":0,"consistentFraming":false,"credible":false,"kind":"none","pairKey":null,"timeline":null},"facts":[{"complete":false,"concentration":null,"confidence":0.9,"excerpt":"Volufiline visibly increases fullness in hollow areas like under the eyes and cheeks, resulting in a plumper, more youthful look.","function":null,"id":"ingredient-volufiline","kind":"ingredient","text":"Volufiline"},{"complete":false,"concentration":null,"confidence":0.9,"excerpt":"Enriched with PDRN—a regenerative ingredient—plus Collagen, NAD, Peptides, and Retinol, it deeply supports skin elasticity, hydration, and resilience, promoting a firm and smooth surface.","function":null,"id":"ingredient-pdrn","kind":"ingredient","text":"PDRN"},{"complete":false,"concentration":null,"confidence":0.9,"excerpt":"Enriched with PDRN—a regenerative ingredient—plus Collagen, NAD, Peptides, and Retinol, it deeply supports skin elasticity, hydration, and resilience, promoting a firm and smooth surface.","function":null,"id":"ingredient-collagen","kind":"ingredient","text":"Collagen"},{"complete":false,"concentration":null,"confidence":0.9,"excerpt":"Enriched with PDRN—a regenerative ingredient—plus Collagen, NAD, Peptides, and Retinol, it deeply supports skin elasticity, hydration, and resilience, promoting a firm and smooth surface.","function":null,"id":"ingredient-nad","kind":"ingredient","text":"NAD"},{"complete":false,"concentration":null,"confidence":0.9,"excerpt":"Enriched with PDRN—a regenerative ingredient—plus Collagen, NAD, Peptides, and Retinol, it deeply supports skin elasticity, hydration, and resilience, promoting a firm and smooth surface.","function":null,"id":"ingredient-peptides","kind":"ingredient","text":"Peptides"},{"complete":false,"concentration":null,"confidence":0.9,"excerpt":"Enriched with PDRN—a regenerative ingredient—plus Collagen, NAD, Peptides, and Retinol, it deeply supports skin elasticity, hydration, and resilience, promoting a firm and smooth surface.","function":null,"id":"ingredient-retinol","kind":"ingredient","text":"Retinol"},{"complete":false,"concentration":null,"confidence":0.9,"excerpt":"The inclusion of caffeine and vitamin E works against dark circles, puffiness, and uneven skin tone, leaving your complexion brighter and more balanced.","function":null,"id":"ingredient-caffeine","kind":"ingredient","text":"caffeine"},{"complete":false,"concentration":null,"confidence":0.9,"excerpt":"The inclusion of caffeine and vitamin E works against dark circles, puffiness, and uneven skin tone, leaving your complexion brighter and more balanced.","function":null,"id":"ingredient-vitamin E","kind":"ingredient","text":"vitamin E"},{"complete":false,"concentration":null,"confidence":0.9,"excerpt":"Free from artificial colors and fragrances, it’s gentle enough to use around sensitive areas like the under-eye and lips, making it suitable for all skin types, including sensitive skin.","function":null,"id":"skin_type-sensitive","kind":"skin_type","text":"suitable for all skin types, including sensitive skin"},{"complete":false,"concentration":null,"confidence":0.9,"excerpt":"Free from artificial colors and fragrances, it’s gentle enough to use around sensitive areas like the under-eye and lips, making it suitable for all skin types, including sensitive skin.","function":null,"id":"warning-artificial colors and fragrances","kind":"warning","text":"Free from artificial colors and fragrances"}],"ocrText":"Youthful Glow Multi-Balm Stick\nThis multi-purpose balm stick is a powerful skincare solution designed to rejuvenate and enhance your face and body with minimal effort. Crafted in a convenient, hygienic stick format, it offers targeted application that easily fits into your busy lifestyle. Whether you''re dealing with hollow cheeks, fine lines, dark circles, dullness, or loss of firmness, this all-in-one balm works to restore a more youthful, radiant appearance. Ideal for women juggling careers, family, and self-care, this product addresses common signs of aging and skin fatigue. It aims to boost confidence by delivering quick, visible improvements, helping you look refreshed and vibrant throughout the day. No more complicated routines or multiple products—just one effective solution to achieve that glow. At the heart of this balm is a blend of advanced ingredients. Volufiline visibly increases fullness in hollow areas like under the eyes and cheeks, resulting in a plumper, more youthful look. Enriched with PDRN—a regenerative ingredient—plus Collagen, NAD, Peptides, and Retinol, it deeply supports skin elasticity, hydration, and resilience, promoting a firm and smooth surface. The inclusion of caffeine and vitamin E works against dark circles, puffiness, and uneven skin tone, leaving your complexion brighter and more balanced. The balm’s rich, melting texture glides effortlessly onto the skin, delivering a comfortable, non-sticky feel that doesn’t interfere with your daily activities. Its stick format makes precise, mess-free application simple—perfect for quick touch-ups throughout the day, whether at home, at work, or on the go. Free from artificial colors and fragrances, it’s gentle enough to use around sensitive areas like the under-eye and lips, making it suitable for all skin types, including sensitive skin. Imagine starting each day with skin that feels as good as it looks—more radiant, plump, and resilient. This balm empowers you to maintain a natural, youthful glow effortlessly, 