INSERT INTO product_image_analysis (product_id, fingerprint, source, work, information, published, status, updated_at) VALUES ('10691188621452', 'ab2743f321becae1af60c9980f7013ee18b26eebe998e0dcc28eae5f562a2bca', '{"id":"gid://shopify/Product/10691188621452","title":"Radiance & Pore Refinement Pads","handle":"radiance-pore-refinement-pads","productType":"","vendor":"Maison & Co.","description":"This innovative skin treatment is designed to deliver deep cleansing, gentle exfoliation, and pore refinement in one easy-to-use pad. Crafted with the purest natural ingredients, it harnesses the potent power of White Willow Bark—nature’s own BHA—known for its ability to penetrate pores and dissolve excess oil and dead skin cells without irritation. Complemented by Citric Acid (AHA), this formula gently resurfaces skin, revealing a brighter, smoother, and more even complexion with each use. Ideal for those who struggle with enlarged pores, persistent oiliness, and uneven skin texture, this treatment is a game-changer for anyone seeking a clear, matte, and flawless look. It perfectly fits into a busy lifestyle, providing quick, effective results that keep skin looking fresh and radiant without harshness or downtime. Each pad offers a dual-action experience: the embossed side efficiently exfoliates by removing impurities and excess oil, while the silky side leaves your skin feeling ultra-smooth and prepared for the next step in your skincare routine. Infused with calming botanical extracts and aromatic lavender, every application becomes a soothing ritual, transforming skincare from a chore into a moment of relaxation and self-care. The benefits extend beyond just cleansing—this treatment significantly reduces pore waste by up to 87.3% and sebum/oil production by 47.1%, boosting your confidence with visibly clearer, healthier skin that radiates calm and vitality. Because it combines scientific efficacy with natural soothing ingredients, it outperforms conventional toners and exfoliants—delivering quicker, reliable results that help you achieve your skincare goals faster. Experience smoother, clearer, more balanced skin that feels as good as it looks—confident, refreshed, and ready to take on any day with a youthful glow.","descriptionHtml":"This innovative skin treatment is designed to deliver deep cleansing, gentle exfoliation, and pore refinement in one easy-to-use pad. Crafted with the purest natural ingredients, it harnesses the potent power of White Willow Bark—nature’s own BHA—known for its ability to penetrate pores and dissolve excess oil and dead skin cells without irritation. Complemented by Citric Acid (AHA), this formula gently resurfaces skin, revealing a brighter, smoother, and more even complexion with each use.\n\nIdeal for those who struggle with enlarged pores, persistent oiliness, and uneven skin texture, this treatment is a game-changer for anyone seeking a clear, matte, and flawless look. It perfectly fits into a busy lifestyle, providing quick, effective results that keep skin looking fresh and radiant without harshness or downtime.\n\nEach pad offers a dual-action experience: the embossed side efficiently exfoliates by removing impurities and excess oil, while the silky side leaves your skin feeling ultra-smooth and prepared for the next step in your skincare routine. Infused with calming botanical extracts and aromatic lavender, every application becomes a soothing ritual, transforming skincare from a chore into a moment of relaxation and self-care.\n\nThe benefits extend beyond just cleansing—this treatment significantly reduces pore waste by up to 87.3% and sebum/oil production by 47.1%, boosting your confidence with visibly clearer, healthier skin that radiates calm and vitality. Because it combines scientific efficacy with natural soothing ingredients, it outperforms conventional toners and exfoliants—delivering quicker, reliable results that help you achieve your skincare goals faster.\n\nExperience smoother, 