INSERT INTO product_image_analysis (product_id, fingerprint, source, work, information, published, status, updated_at) VALUES ('10705876549772', '83922e5d75737f3f5ea3965e0d7314cec9078173624f4f6db82e4c937fce46ff', '{"id":"gid://shopify/Product/10705876549772","title":"Bio-Collagen Real Deep Mask, Hydrating Overnight Hydrogel Face Mask, Pore Minimizing, Elasticity, Plumping, Travel Essentials & Self Care Gifts for Women, Korean Skin Care | 1.19Oz(34G) X 4Ea","handle":"bio-collagen-real-deep-mask-hydrating-overnight-hydrogel-face-mask-pore-minimizing-elasticity-plumping-travel-essentials-self-care-gifts-for-women-korean-skin-care-1-19oz34g-x-4ea","productType":"","vendor":"Li Fei Beauty","description":"Product description PORE TIGHTENING & FIRMING: Formulated with ultra-low molecular collagen, this mask maximizes penetration and absorption. It refines enlarged pores, improves skin elasticity, and visibly smooths fine lines and wrinkles instantly. DEEP HYDRATION: The oligo-hyaluronic acid in the Biodance Bio-Collagen Real Deep Mask provides superior moisturizing effects compared to regular hyaluronic acid. It quickly hydrates the skin''s surface and penetrates deeper layers, leaving the complexion healthy and well-moisturized. BRIGHTENS THE SKIN: Formulated with Galactomyces Ferment Filtrate and Niacinamide, it improves uneven skin tone and texture while offering antioxidant effects, resulting in healthier, more radiant skin. UNIQUE OVERNIGHT ABSORPTION: Each 1.19 oz bottle of essence is solidified into each mask sheet. Unlike regular sheet masks, our signature hydrogel mask becomes transparent as active ingredients melt deep into the skin. Recommended for overnight use or a minimum of 3-4 hours for a flawless glass-skin glow. SAFE FOR SENSITIVE SKIN: Formulated with non-toxic, non-irritant ingredients and completely free from 19 controversial substances. We ensure safe, hypoallergenic care that delivers deep, long-lasting improvements beyond temporary effects.","descriptionHtml":"<div> <div> <h2>Product description</h2> </div> </div> <ul>\n<li>PORE TIGHTENING &amp; FIRMING: Formulated with ultra-low molecular collagen, this mask maximizes penetration and absorption. It refines enlarged pores, improves skin elasticity, and visibly smooths fine lines and wrinkles instantly.</li>\n<li>DEEP HYDRATION: The oligo-hyaluronic acid in the Biodance Bio-Collagen Real Deep Mask provides superior moisturizing effects compared to regular hyaluronic acid. It quickly hydrates the skin''s surface and penetrates deeper layers, leaving the complexion healthy and well-moisturized.</li>\n<li>BRIGHTENS THE SKIN: Formulated with Galactomyces Ferment Filtrate and Niacinamide, it improves uneven skin tone and texture while offering antioxidant effects, resulting in healthier, more radiant skin.</li>\n<li>UNIQUE OVERNIGHT ABSORPTION: Each 1.19 oz bottle of essence is solidified into each mask sheet. Unlike regular sheet masks, our signature hydrogel mask becomes transparent as active ingredients melt deep into the skin. Recommended for overnight use or a minimum of 3-4 hours for a flawless glass-skin glow.</li>\n<li>SAFE FOR SENSITIVE SKIN: Formulated with non-toxic, non-irritant ingredients and completely free from 19 controversial substances. We ensure safe, hypoallergenic care that delivers deep, long-lasting improvements beyond temporary effects.</li>\n</ul>","tags":[],"updatedAt":"2026-10-10T12:25:07Z","productId":"10705876549772","metadata":[],"metadataAccessible":false,"images":[{"id":"gid://shopify/ProductImage/52139808424076","url":"https://cdn.shopify.com/s/files/1/0795/9570/0364/files/a12784540062bb7f0fa59e72c7b940c8.jpg?v=1791437181","width":1000,"height":1000,"altText":"Bio-Collagen Real Deep Mask, Hydrating Overnight Hydrogel Face Mask, Pore Minimizing, Elasticity, Plumping, Travel Essentials & Self Care Gifts for Women, Korean Skin Care | 1.19Oz(34G) X 4Ea"},{"id":"gid://shopify/ProductImage/52139808456844","url":"https://cdn.shopify.com/s/