INSERT INTO product_image_analysis (product_id, fingerprint, source, work, information, published, status, updated_at) VALUES ('10705876779148', 'e4f88dbdd724aa4e453c87af710ba3fedcfdba79185e884bc0ab5d07cb5ffb6f', '{"id":"gid://shopify/Product/10705876779148","title":"Kojic Acid Turmeric Clarifying Capsule Serum for Troubled Skin","handle":"kojic-acid-turmeric-clarifying-capsule-serum-for-troubled-skin","productType":"","vendor":"Li Fei Beauty","description":"Product description [Kojic Acid & Turmeric for Troubled Skin] Kojic Acid helps fade the look of uneven patches and brighten overall tone, while antioxidant-rich Turmeric soothes stressed skin—together supporting a clearer, more balanced-looking complexion. [Hero Ingredients] A targeted blend of Kojic Acid, Turmeric, Niacinamide, and Glow Capsules helps improve uneven skin tone and texture—ideal for use after spot care. [Snowflake-like Capsules for Hydration & Barrier Care] Snowflake-like micro-capsules release Squalane and Thioctic Acid on contact, supporting the skin''s moisture barrier and restore a healthy, radiant glow. [Dermatologist-Tested & Gentle] Clinically tested and proven suitable for all skin types, including delicate skin. *Clinical Tested by the Global Institute of Dermatological Sciences/ Results may vary depending on individual skin types.","descriptionHtml":"<div> <div> <h2>Product description</h2> </div> </div> <ul>\n<li>[Kojic Acid &amp; Turmeric for Troubled Skin] Kojic Acid helps fade the look of uneven patches and brighten overall tone, while antioxidant-rich Turmeric soothes stressed skin—together supporting a clearer, more balanced-looking complexion.</li>\n<li>[Hero Ingredients] A targeted blend of Kojic Acid, Turmeric, Niacinamide, and Glow Capsules helps improve uneven skin tone and texture—ideal for use after spot care.</li>\n<li>[Snowflake-like Capsules for Hydration &amp; Barrier Care] Snowflake-like micro-capsules release Squalane and Thioctic Acid on contact, supporting the skin'